package fr.gemsofrod.encyclopedie.data

/** Nederlandse vertalingen van de naam en de beschrijvende teksten van de fossielen. */
object FossileTranslationsNl {
    val data: Map<String, FossileTranslation> = mapOf(
        "fossile-ammonite-madagascar" to FossileTranslation(
            nom = "Ammoniet van Madagaskar",
            descriptionCourte = "Het meest iconische fossiel: de verkalkte spiraal van een zeecefalopode die samen met de dinosauriërs uitstierf.",
            descriptionLongue = "Ammonieten zijn zeecefalopoden verwant aan de huidige nautilus en octopus, waarvan de spiraalvormig opgerolde schelp bij miljoenen is gefossiliseerd langs de oude kusten van het Krijt op Madagaskar. Gezaagd en gepolijst onthullen ze hun interne kamerscheidingen (suturen) in geometrische motieven, gewaardeerd in decoratie en in instapjuwelen.",
            interetJoaillerie = "Goed: gepolijste schijven als hangers, complete exemplaren voor decoratie en beginnende verzamelingen"
        ),
        "fossile-ammolite" to FossileTranslation(
            nom = "Ammoliet",
            descriptionCourte = "Het enige fossiel dat officieel als edelsteen erkend is, met een iriserende glans die wedijvert met opaal.",
            descriptionLongue = "Ammoliet komt uit een wereldwijd unieke vindplaats, langs de St. Mary's-rivier in Alberta, waar het aragoniet parelmoer van bepaalde reusachtige ammonieten intact bewaard is gebleven in plaats van te herkristalliseren tot calciet. Het resultaat is een spectaculaire iriserende glans, zo fijn en breekbaar dat hij bijna altijd wordt beschermd door een doublet of triplet voordat hij wordt gezet. De CIBJO classificeerde hem in 1981 officieel als organische edelsteen, naast parel, koraal en barnsteen.",
            interetJoaillerie = "Hoog: gezette cabochons, doublets en triplets, zeer gegeerd om zijn iridescentie die vergelijkbaar is met opaal"
        ),
        "fossile-orthocere" to FossileTranslation(
            nom = "Orthoceras",
            descriptionCourte = "Een cefalopode met een rechte, langwerpige kegelvormige schelp, een verre voorouder van de inktvis.",
            descriptionLongue = "In tegenstelling tot de opgerolde ammoniet had de orthoceras een rechte, in kamers verdeelde kegelvormige schelp, waarin het dier zijn drijfvermogen regelde zoals de nautilus dat vandaag nog doet. De Marokkaanse kalkstenen platen, doorspekt met doorsneden van orthoceren en andere mariene ongewervelden, worden veelvuldig gebruikt als vloertegels en gepolijste decoratieve objecten.",
            interetJoaillerie = "Matig: voornamelijk decoratie (platen, wastafels, dienbladen) eerder dan juwelen"
        ),
        "fossile-goniatite" to FossileTranslation(
            nom = "Goniatiet",
            descriptionCourte = "De directe voorouder van de ammoniet, herkenbaar aan zijn eenvoudigere, zigzaggende interne kamerscheidingen.",
            descriptionLongue = "Goniatieten verschenen al vóór de ammonieten in het Devoon en delen dezelfde spiraalvormige silhouet, maar vertonen eenvoudigere, zaagtandvormige interne suturen. Marokko levert opmerkelijk goed bewaarde exemplaren, vaak ruw of licht gepolijst verkocht om de schelp te tonen zonder het natuurlijke reliëf uit te wissen.",
            interetJoaillerie = "Matig: verzamelstukken en ruw gepolijste hangers"
        ),
        "fossile-trilobite-elrathia" to FossileTranslation(
            nom = "Trilobiet Elrathia kingii",
            descriptionCourte = "De meest algemeen gevonden trilobiet ter wereld, bij miljoenen gewonnen uit één en dezelfde vindplaats in Utah.",
            descriptionLongue = "Elrathia kingii is een kleine trilobiet uit het Midden-Cambrium, in aanzienlijke hoeveelheden gewonnen uit de schalies van de Wheeler-formatie in Utah — een vindplaats zo productief dat ze vrijwel alle wereldwijd in de handel verkochte trilobieten levert. Zijn karakteristieke driedelige segmentatie (kop, borststuk, staartschild) maakt hem een uitstekend educatief exemplaar om de anatomie te begrijpen van deze groep geleedpotigen, die sinds het einde van het Perm is uitgestorven.",
            interetJoaillerie = "Laag: voornamelijk verzamelstuk, soms ruw gezet als beschermde hanger"
        ),
        "fossile-trilobite-phacops" to FossileTranslation(
            nom = "Trilobiet Phacops rana",
            descriptionCourte = "De favoriete trilobiet onder verzamelaars, beroemd om zijn grote samengestelde ogen met calcietfacetten.",
            descriptionLongue = "Phacops rana is ongetwijfeld de meest gegeerde trilobiet bij verzamelaars vanwege zijn opvallende halfronde ogen, gevormd door tientallen individuele calcietlenzen — een van de allereerste complexe optische systemen in de evolutie. De Marokkaanse ateliers van Alnif hebben zich gespecialiseerd in de nauwgezette preparatie van deze stukken, met een pneumatische naald vrijgelegd om het volledige reliëf te tonen van het dier, opgerold in verdedigingshouding.",
            interetJoaillerie = "Laag: voornamelijk verzamelstuk en decoratie"
        ),
        "fossile-trilobite-calymene" to FossileTranslation(
            nom = "Trilobiet Calymene",
            descriptionCourte = "Een klassieke en betaalbare trilobiet, vaak gevonden opgerold als een fossiele pissebed.",
            descriptionLongue = "Het geslacht Calymene, wijdverspreid in de Marokkaanse vindplaatsen en lange tijd in Engeland bekend onder de bijnaam \"Dudley bug\", onderscheidt zich door zijn vermogen om zich volledig op te rollen in verdedigingshouding, precies zoals een hedendaagse pissebed. Dit gefossiliseerde \"opgerolde\" gedrag is een van de meest voorkomende introductie-exemplaren voor beginnende verzamelaars.",
            interetJoaillerie = "Laag: verzamelstuk en decoratie"
        ),
        "fossile-dent-megalodon" to FossileTranslation(
            nom = "Megalodontand",
            descriptionCourte = "De tand van de grootste haai die ooit heeft bestaan, soms meer dan 18 cm hoog.",
            descriptionLongue = "De megalodon, een reusachtige haai die ongeveer 3,6 miljoen jaar geleden uitstierf, kon 15 tot 18 meter lang worden. Zijn massieve driehoekige tanden, gekarteld zoals die van de huidige grote witte haai maar veel groter, mineraliseerden in het sediment en namen daarbij, afhankelijk van de vindplaats, uiteenlopende tinten aan. De mooiste stukken, symmetrisch en zonder slijtage, halen hoge prijzen zowel bij verzamelaars als in ruwe sieraden.",
            interetJoaillerie = "Hoog: ruwe hangers gezet in klauwzettingen, zeer gevraagd in decoratieve juwelen"
        ),
        "fossile-os-dinosaure-gembone" to FossileTranslation(
            nom = "Geagatiseerd dinosaurusbot (\"gembone\")",
            descriptionCourte = "Een dinosaurusbot dat molecuul voor molecuul volledig is vervangen door gekleurde agaat.",
            descriptionLongue = "In sommige vindplaatsen uit het Amerikaanse Jura hebben begraven dinosaurusbotten een volledige silicificatie ondergaan: het oorspronkelijke botmateriaal werd opgelost en geleidelijk vervangen door gekleurde silica, waarbij de poreuze celstructuur van het bot getrouw bewaard bleef terwijl het veranderde in slijpbare agaat. Het resultaat, door lapidairs \"gembone\" genoemd, combineert de wetenschappelijke waarde van een authentiek dinosaurusfossiel met de esthetische aantrekkingskracht van een halfedelsteen met unieke motieven.",
            interetJoaillerie = "Hoog: zeer gegeerde cabochons, uniek cellulair motief dat onmogelijk na te bootsen is"
        ),
        "fossile-poisson-green-river" to FossileTranslation(
            nom = "Fossiele vis van Green River",
            descriptionCourte = "Hele scholen kleine vissen, vastgelegd in een merenkalksteen van uitzonderlijke fijnheid.",
            descriptionLongue = "Het voormalige Fossielmeer in Wyoming heeft in fijn gelaagde sedimenten tienduizenden zoetwatervissen bewaard in uitzonderlijk goede staat — schubben, vinnen en soms zelfs de maaginhoud intact. De Green River-formatie is vandaag een van de meest productieve vindplaatsen van gewervelde fossielen ter wereld, in de open lucht ontgonnen en verkocht als gezaagde platen voor decoratie.",
            interetJoaillerie = "Matig: ingelijste platen, eerder decoratieve objecten dan juwelen"
        ),
        "fossile-dent-mosasaure" to FossileTranslation(
            nom = "Mosasaurustand",
            descriptionCourte = "De kegelvormige tand van een groot marien roofreptiel, een verre neef van de huidige varanen.",
            descriptionLongue = "Mosasauriërs waren grote mariene roofreptielen, verwant aan de huidige varanen, die de zeeën domineerden aan het einde van het Krijt, vlak vóór de uitstervingsgebeurtenis die ook de niet-vogelachtige dinosauriërs trof. De Marokkaanse fosfaatafzettingen van Khouribga, wereldwijd bekend om hun rijkdom aan gefossiliseerde mariene gewervelden, leveren regelmatig goed bewaarde kegelvormige tanden op, gewaardeerd door verzamelaars om hun spectaculaire vorm.",
            interetJoaillerie = "Matig: ruwe hangers, hoge verzamelwaarde"
        ),
        "fossile-ivoire-mammouth" to FossileTranslation(
            nom = "Fossiel mammoetivoor",
            descriptionCourte = "Het ivoor van een verdwenen reus uit de laatste ijstijd, vrijgekomen door het dooien van de Siberische permafrost.",
            descriptionLongue = "De geleidelijke opwarming van de Siberische permafrost brengt elk jaar slagtanden van wolharige mammoeten aan het licht, soms opmerkelijk goed bewaard na tienduizenden jaren begraven te hebben gelegen in het ijs. Deze legale en gereglementeerde handel, in tegenstelling tot modern olifantivoor, voorziet beeldhouwers en juweliers van een materiaal met een textuur en korrel die dicht bij levend ivoor liggen, soms verrijkt met spectaculaire blauwgroene tinten door oppervlakkige mineralisatie met ijzerfosfaat (vivianiet).",
            interetJoaillerie = "Hoog: beeldhouwwerken, juwelen, inlegwerk — wettelijk gereguleerde handel, in tegenstelling tot hedendaags olifantivoor"
        ),
        "fossile-bois-petrifie" to FossileTranslation(
            nom = "Versteend hout",
            descriptionCourte = "Een hele boomstam, ring na ring, omgezet in steen door infiltratie van silica.",
            descriptionLongue = "Wanneer een boomstam valt en snel begraven raakt in een met silica verzadigd sediment, dringt het rijke silicaathoudende water geleidelijk in de celstructuur van het hout en vervangt het, vezel na vezel, voordat de ontbinding het kan uitwissen. Het resultaat behoudt de textuur, de groeiringen en soms zelfs de insecten die de bast hadden aangevreten, terwijl het de hardheid en de glans van agaat verwerft — vandaar de populariteit ervan, zowel in juwelen als in groot decoratief meubilair.",
            interetJoaillerie = "Hoog: cabochons en juwelen, ook zeer gevraagd in decoratie (dienbladen, tafelbladen)"
        ),
        "fossile-fougere" to FossileTranslation(
            nom = "Fossiele varen",
            descriptionCourte = "De delicate koolstofafdruk van een varen uit de immense moerasbossen van het Carboon.",
            descriptionLongue = "De uitgestrekte moerasbossen van het Carboon, oorsprong van de meeste huidige steenkoollagen, hebben in hun kleischalies talloze afdrukken van varens en zaadvarens achtergelaten, bewaard als een fijn koolstoflaagje. Deze plaatjes, verkregen door de rots te splijten langs het vlak van het gefossiliseerde blad, tonen nerven van opmerkelijke fijnheid voor planten die meer dan 300 miljoen jaar oud zijn.",
            interetJoaillerie = "Laag: voornamelijk verzamelstuk en ingelijste wanddecoratie"
        ),
        "fossile-ambre-baltique" to FossileTranslation(
            nom = "Baltische barnsteen",
            descriptionCourte = "De gefossiliseerde hars van verdwenen naaldbossen, de oudste organische edelsteen in de menselijke juweliersgeschiedenis.",
            descriptionLongue = "Baltische barnsteen ontstond ongeveer 44 miljoen jaar geleden uit de hars van reusachtige, nu uitgestorven naaldbomen, waarvan de bossen ooit Noord-Europa bedekten. Meegevoerd door waterlopen en na stormen aangespoeld op de stranden van de Oostzee, wordt hij al sinds de bronstijd door de mens bewerkt en verhandeld — de barnsteenhandelsroutes behoren tot de oudste gedocumenteerde handelswegen van Europa.",
            interetJoaillerie = "Hoog: traditionele Noord-Europese juwelen sinds de bronstijd"
        ),
        "fossile-ambre-inclusion" to FossileTranslation(
            nom = "Barnsteen met inclusie van een insect",
            descriptionCourte = "Een mug, een mier of een bloem voor eeuwig vastgelegd in een druppel hars die tot steen werd.",
            descriptionLongue = "Dominicaanse barnsteen, jonger en over het algemeen transparanter dan Baltische barnsteen, dankt zijn faam aan de uitzonderlijke rijkdom van zijn inclusies: insecten, spinnen, kleine bloemen en soms zelfs kleine gewervelden zitten er met een weelde aan details in gevangen, wat dit fossiel beroemd heeft gemaakt ver buiten kringen van verzamelaars, mede gepopulariseerd door fictie rond DNA bewaard in barnsteen.",
            interetJoaillerie = "Hoog: elke inclusie is uniek, hoge toegevoegde waarde in verzamelaarsjuwelen"
        ),
        "fossile-copal" to FossileTranslation(
            nom = "Copal",
            descriptionCourte = "Het \"tienerstadium\" van barnsteen: een fossiele hars die nog te jong is om volledig gepolymeriseerd te zijn.",
            descriptionLongue = "Copal is een plantaardige hars die de trage chemische polymerisatie, die over miljoenen jaren een hars in echte barnsteen verandert, nog niet heeft voltooid. Zachter, beter oplosbaar in oplosmiddelen en vaak transparanter, wordt hij soms ten onrechte als barnsteen verkocht — een eenvoudige acetontest (die copal aan het oppervlak plakkerig maakt, zonder effect op echte barnsteen) maakt het mogelijk ze te onderscheiden.",
            interetJoaillerie = "Matig: lokale ambachtelijke juwelen, duidelijk te onderscheiden van barnsteen in een verkoopfiche"
        ),
        "fossile-corail-agatise" to FossileTranslation(
            nom = "Geagatiseerd fossiel koraal",
            descriptionCourte = "Een heel koraalrif veranderd in agaat, elke poliep vastgelegd als een bloem van silica.",
            descriptionLongue = "In Florida raakten oude koraalriffen gesilicificeerd door grondwater rijk aan silica, waarbij elke koraalpoliep getrouw werd vervangen door chalcedoon met behoud van zijn karakteristieke stervormige structuur. Eenmaal gesneden en gepolijst roept het resultaat natuurlijke bloemmotieven op, zo regelmatig dat het soms wordt verward met een kunstmatige creatie — het werd in 1979 uitgeroepen tot officiële steen van de staat Florida.",
            interetJoaillerie = "Hoog: cabochons met unieke bloemmotieven, gewaardeerd in regionale en internationale juwelen"
        ),
        "fossile-oursin" to FossileTranslation(
            nom = "Fossiele zee-egel",
            descriptionCourte = "Het kalkskelet met perfecte symmetrie van een zee-egel, lange tijd gedragen als talisman.",
            descriptionLongue = "De skeletten (schelpen) van fossiele zee-egels, met hun karakteristieke vijfstralige radiale symmetrie, worden in overvloed aangetroffen in de krijtlagen van het Krijt in Europa en Noord-Afrika. In de Europese folklore bijgenaamd \"feebrood\" of \"Sint-Pietersstenen\", werden ze traditioneel bewaard als geluksbrenger of bescherming van de haard, lang voordat ze wetenschappelijk werden bestudeerd.",
            interetJoaillerie = "Laag tot matig: traditioneel gedragen als ruwe hanger (\"Sint-Pietersteen\" of \"feebrood\" in Europa)"
        ),
        "fossile-crinoide" to FossileTranslation(
            nom = "Crinoïde (entrochiet)",
            descriptionCourte = "De opgestapelde kalkringen van de steel van een \"zeelelie\", een vastzittend stekelhuidig dier en geen plant.",
            descriptionLongue = "Ondanks zijn misleidende naam \"zeelelie\" is de crinoïde een stekelhuidig dier, verwant aan de zee-egel en de zeester, dat met een lange gelede steel aan de zeebodem vastzat. Deze steel, opgebouwd uit gestapelde kalkringen als muntstukken, valt na de dood van het dier makkelijk uiteen en wordt in overvloed aangetroffen in bepaalde kalkstenen, die geologen na polijsten tot plaat een entrochietkalksteen noemen.",
            interetJoaillerie = "Matig: platen en decoratieve objecten eerder dan juwelen, soms cabochons voor losse steeldelen"
        ),
        "fossile-stromatolite" to FossileTranslation(
            nom = "Fossiele stromatoliet",
            descriptionCourte = "De oudste bekende levenssporen op aarde, laag na laag opgebouwd door bacteriekolonies.",
            descriptionLongue = "Stromatolieten zijn geen overblijfselen van een individueel organisme, maar gelaagde sedimentaire structuren, geduldig laag na laag opgebouwd door kolonies cyanobacteriën die sediment vasthielden en calciumcarbonaat neersloegen. Sommige Australische vindplaatsen behoren tot de oudste geïdentificeerde levenssporen op aarde, met een ouderdom van meer dan 3,4 miljard jaar — een direct getuigenis van de allereerste ecosystemen van de planeet, tegenwoordig gepolijst tot decoratieve platen om hun unieke concentrische motief.",
            interetJoaillerie = "Laag tot matig: decoratieve platen, af en toe cabochons voor de gesilicificeerde variëteiten"
        ),
        "fossile-belemnite" to FossileTranslation(
            nom = "Belemniet",
            descriptionCourte = "De gefossiliseerde \"rostrum\" van een prehistorische inktvis, in de folklore lange tijd verward met een bliksemsteen.",
            descriptionLongue = "Wat men gefossiliseerd aantreft, is niet het hele dier maar zijn rostrum, een stevige interne kalkstructuur die diende als tegengewicht en steun voor het zachte lichaam van deze cefalopode, een uitgestorven neef van de huidige inktvissen. Zijn kegelvormige, langwerpige vorm, in de Europese volksfolklore vaak verward met een uit de hemel gevallen \"bliksemsteen\", maakt er een fossiel van dat zelfs door niet-specialisten gemakkelijk te herkennen is.",
            interetJoaillerie = "Laag: verzamelstuk, af en toe ruwe hangers"
        )
    )
}
